from delta.tables import DeltaTable

def merge_seguro(df_origem, tabela, chave):
    dup = df_origem.groupBy(chave).count().filter("count > 1").limit(1).count()
    if dup:
        raise ValueError(f"Origem com chaves duplicadas em {chave}")
    alvo = DeltaTable.forName(spark, tabela)
    cond = " AND ".join(f"t.{c} = s.{c}" for c in chave)
    (alvo.alias("t").merge(df_origem.alias("s"), cond)
         .whenMatchedUpdateAll().whenNotMatchedInsertAll().execute())
    return alvo.history(1).select("version", "operationMetrics").first()

