def checar_grao(df, chaves):
    linhas = df.count()
    distintas = df.select(*chaves).distinct().count()
    resumo = {"linhas": linhas, "chaves": distintas, "excedente": linhas - distintas}
    if resumo["excedente"] > 0:
        raise ValueError(f"Grão {chaves} violado: {resumo}")
    return resumo

